import{_ as a,o as e,c as o,a3 as r}from"./chunks/framework.Dz5Q8p4s.js";const c=JSON.parse('{"title":"In-Video Instructions: Visual Signals as Generative Control","description":"","frontmatter":{"title":"In-Video Instructions: Visual Signals as Generative Control","arxiv":"2511.19401","date":"2025-11-24","authors":"Gongfan Fang, Xinyin Ma, Xinchao Wang","categories":"cs.CV, cs.AI","topics":"可控视频生成, 视觉指令, 空间定位","outline":[2,2]},"headers":[],"relativePath":"papers/2511.19401.md","filePath":"papers/2511.19401.md","lastUpdated":null}'),n={name:"papers/2511.19401.md"};function i(p,t,s,l,d,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="in-video-instructions-visual-signals-as-generative-control" tabindex="-1">In-Video Instructions: Visual Signals as Generative Control <a class="header-anchor" href="#in-video-instructions-visual-signals-as-generative-control" aria-label="Permalink to &quot;In-Video Instructions: Visual Signals as Generative Control&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2511.19401" target="_blank" rel="noreferrer">2511.19401</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-11-24</td></tr><tr><td><strong>作者</strong></td><td>Gongfan Fang, Xinyin Ma, Xinchao Wang</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>把指令直接画在首帧上（短文字 + 箭头），文本 prompt 固定为「按步骤执行指令」，零训练地让视频模型对多物体做互不干扰的空间定位控制。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>大规模视频生成模型已经表现出理解当前帧内容、并按物理与逻辑规则外推后续帧的能力。近期一系列工作把这种能力当作推理能力来用：视觉感知、机械臂操作、拼图求解、甚至数学推理。其中一个被反复观察到的现象是，这些模型能读懂画面里的文字与符号。</p><p>论文抓住这个现象反过来问：既然模型能读懂画面里的符号，那么符号能不能反过来当作控制信号？</p><p>这个问题的现实意义在于文本控制的一个结构性缺陷。文本 prompt 是全局的、序列化的，它无法自然表达空间对应关系。当画面里有三辆车，你想让左边那辆倒车、中间那辆右转、右边那辆停下，纯文本必须依赖「从左数第几个」这类指代，而模型对这类指代的解析并不可靠。把指令写在对应物体旁边，这个歧义就消失了。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>可控视频生成的既有路线是不断增加条件模态。早期是纯文本到视频（CogVideo、CogVideoX、VideoBooth），把高维视觉内容从低维文本描述里生成出来；文本只能传递粗粒度语义，无法表达复杂时空关系。为此后续工作引入了各种非文本条件：首帧（图生视频）、深度图（DepthCrafter）、Canny 边缘（ControlVideo）、包围框（Boximator）、轨迹（Motion Prompting）、三维条件（DAS）、草图（VideoComposer）、以及各类运动表示。再往后是多条件联合控制的框架（UniAnimate、OmniVDiff、VACE）。</p><p>这些方法能做到细粒度控制，代价是明确的：每一种新条件都需要新的编码器、新的注入模块、以及在配对数据上重新训练或微调。控制信号与模型是绑定的，换一个骨干就要重做一遍。而对闭源的商业模型（Veo、Kling），这条路根本走不通——用户拿不到权重。</p><p>另一条线是把视频模型当作零样本推理器的研究，它们发现模型能理解嵌入视频中的文本与符号信息，但目的是评估理解能力，没有把这种能力转化为控制接口。</p><p>本文的定位正好落在这两条线的空隙：用一个不需要任何训练、对闭源模型同样可用的接口，拿到接近专用条件模块的空间控制粒度。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>已有的观察摆在那里：视频模型能读懂画面中的文字和符号；图生视频模型接受一张首帧作为条件；这张首帧是用户完全可控的一张普通图像。</p><p>把这三件事放在一起，结论几乎是自动的——如果我在首帧上写字，模型会把这些字当作场景的一部分来理解，而模型的任务是「预测这个场景接下来会怎样」。一个写着「向左飞」的箭头出现在热气球旁边，模型对「接下来会发生什么」的最合理续写就是热气球向左飞。控制信号不需要新的通道，它借用了模型原本用来感知的通道。</p><p>再往下想一层，为什么这比文本更好？因为文本进入模型时不带位置，而画在画面上的文字天然带位置。空间指代问题在文本域里是一个需要推理的绑定问题，在图像域里是一个不需要推理的共位问题。这个观察不依赖本文的任何贡献，任何了解图生视频接口的人都能推出来。</p><p>剩下的就是设计问题：用什么符号？作者选了最小的两种——短文字命令（说做什么）和箭头（说对谁做、往哪个方向做）。多步指令用编号（「1. 指令一」「2. 指令二」）表达顺序。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>视频模型预测未来帧时会把画面里的一切都当作场景证据，包括你写在上面的字和画上去的箭头。于是控制不需要新的输入通道：把指令画在目标物体旁边，模型对「接下来会发生什么」的最自然续写，就是执行这条指令。文本 prompt 做不到这一点，因为文本进入模型时不携带位置信息，而画在画布上的指令自带空间锚点。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>方法本身极简，没有任何训练或架构改动。</p><p><strong>构造指令帧。</strong> 从一张包含若干目标物体的初始帧开始，叠加两类基本元素：短文字命令（描述某个主体的预期行为）、箭头（定位目标，并可传达方向或影响范围）。文字的位置是灵活的——可以放在目标区域内部形成直接关联，也可以放在画面外侧以保持场景干净，此时用箭头建立空间连接。多条指令可以共存，形成一对一或一对多的对应；多步指令通过编号表达时序。</p><p><strong>生成。</strong> 把标注后的帧作为图生视频的首帧条件，文本 prompt 固定为一句 <code>Follow the instructions step by step.</code>。作者指出这句文本是可选的，甚至可以直接写在画布上实现完全的统一控制。不做任何微调或架构修改。指令只出现在首帧，后续帧由模型自由合成，它需要自己把意图传播下去。</p><p>一个具体例子（论文图 6d）：一张街道图里有三辆车，分别在旁边写上「倒车」「右转」「停下」并各配一个箭头指向对应车辆。生成结果中三辆车各自执行不同动作，场景动态保持连贯。作者观察到一个有意思的现象：让白车倒车特别难，因为它正后方还停着另一辆车，模型有很强的先验倾向于让车向前开——在解析物理上合理的轨迹时这个先验压过了指令。</p><p><strong>评测方式。</strong> 主要在 Veo 3.1（默认）、Kling 2.5、Wan 2.2 上做。定量部分只有两处：一是 VBench 上比较「把 prompt 文字嵌成图像上方的 caption」与「直接给文本 prompt」的差异；二是对「多物体多指令」场景每种方法生成 24 条视频、人工判断成功率。其余大量结果是定性的。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>模型能读懂画面里的文字吗？</strong> 把 VBench 的 prompt 文字嵌成图像上方的 caption，输入 prompt 固定为那句「按步骤执行指令」，与直接给文本 prompt 对比。结果是在三个模型上都接近但略低于文本输入：以 Veo3.1 Fast 为例，Subject 0.9710 vs 0.9842，Aesthetic Quality 0.5943 vs 0.6006，Imaging Quality 0.7074 vs 0.7086，Temporal Flickering 0.9710 vs 0.9719；Kling-2.5 与 Wan2.2-A13B 的趋势一致。作者的解释是从视觉内容里解读文字天然比处理显式文本更难，因此略低是预期内的。</p><p>这张表里有一个作者没有强调、但方向一致且在三个模型上都成立的现象：Dynamic Degree 反而是嵌入式指令更高——Veo3.1 为 0.8392 vs 0.7857，Kling-2.5 为 0.5625 vs 0.4218，Wan2.2 为 0.5859 vs 0.4921，其中 Kling 的差距超过 13 个百分点。这说明嵌入指令并没有让模型变得保守，反而诱发了更大的运动幅度（对成因的解释论文未给出，属于观察）。</p><p><strong>空间定位是不是真正的优势？</strong> 这是定性比较：在多物体场景中定位某一个目标并执行动作。文本基线用 ChatGPT 自动生成「从左数第 N 个物体」这类无偏的空间表述，以避免人工措辞的偏向。结果显示嵌入式指令能实现精确无歧义的定位，而纯文本 prompt 在解析物体位置上表现明显受限。</p><p><strong>运动控制能做到什么粒度？</strong> 作者按四类运动逐一给出定性结果：平移（热气球，箭头锚定在物体上，模型能推断方向和幅度）、旋转（大象，曲线箭头传达旋转方向与轴心，不同物体可以被赋予不同的旋转指令并各自独立完成）、轨迹（直接画出连续曲线，模型跟随多段路径并保持动力学真实）、姿态（平滑连贯的姿态调整）。相机运动方面测了七种：静止、左摇、右摇、下俯、上仰、推近、拉远，图像内的文字线索能有效引导。作者自己的判断值得注意——相机运动是全局控制，传统文本 prompt 就能处理得很好，嵌入式指令在这里并非必需；它真正的适用面是需要空间接地的细粒度操控。</p><p><strong>多物体多指令场景下的成功率是多少？</strong> 这是全文唯一的定量对比（表 2，24 条视频、人工评判）：倒车 20.8% vs 文本的 8.3%，右转 58.3% vs 29.2%，停下 95.8% vs 58.3%。三项都是嵌入式指令约为文本的两倍以上。但绝对值同样值得注意——最难的倒车只有 20.8%，也就是说在真正复杂的多物体多指令场景里，这个接口五次里有四次做不到。</p><p><strong>能不能跨帧组合？</strong> 作者展示了用多张种子帧、通过视觉指令协调它们之间的交互来合成视频（全部用 Kling-2.5 生成），说明模型能整合来自不同视觉输入的空间与时间线索。</p><p><strong>局限。</strong> 作者列得很坦率：指令画在图上，会一直留在生成的视频里，通常需要后处理去除；这些标记有时会在合成过程中被遮挡，暗示模型本身就有抑制它们的先验，因此在 prompt 里显式要求去除标注可能进一步改善结果；全文分析以定性为主，缺乏系统评估；所有指令都是手工构造的，而真实视频里本就存在交通灯、路牌这类天然视觉信号，模型能否理解并对它们做出反应仍是开放问题。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：视频模型能读懂画面里的文字与符号，这个此前被当作理解能力来评估的现象，可以反过来当作控制接口。把短文字命令和箭头直接画在首帧上，文本 prompt 固定成一句「按步骤执行指令」，就得到了零训练、对闭源模型同样可用的空间接地控制。它的核心优势不是表达能力更强，而是消除了指代歧义——指令与目标在画布上共位，不需要模型做绑定推理。VBench 上嵌入式指令略低于直接文本输入（说明读图确实比读文本难），但 Dynamic Degree 在三个模型上反而更高；在多物体多指令的定量测试里成功率约为纯文本的两倍以上。代价是指令会残留在输出视频里需要后处理，而且最难的指令绝对成功率只有 20.8%。</p><p><strong>3 句话版</strong>：文本 prompt 不带位置信息，所以在多物体场景里表达「谁做什么」是有歧义的；把指令画在物体旁边就没有这个问题。这个接口零训练、可用于闭源模型，在多物体多指令场景的成功率是纯文本的两倍以上。但绝对成功率仍然低，且标记会留在生成视频里。</p><p><strong>1 句话版</strong>：不要用文本描述你想控制谁，直接在画面上写给它看。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的假设是：<strong>模型会把画布上的标注理解为「要执行的指令」，而不是「要渲染的场景内容」。</strong></p><p>这条假设一旦不成立，方法整个失效。它的失效不是抽象风险，论文自己的观察已经指向了这一点：作者报告标记有时会在合成过程中被遮挡，并推测模型有抑制这些元素的先验。换个角度看，这说明模型对「画面上有字和箭头」这件事的处理并不一致——有时当指令执行，有时当异物抹掉，有时可能两者都做（既执行又保留在画面里，这正是需要后处理的原因）。</p><p>更根本的问题是这种理解从何而来。视频模型的训练数据里包含大量带有叠加文字的内容：字幕、水印、表情包、体育转播的箭头标注、教学视频的标记。模型学到的最可能是「这类叠加物是画面的一部分，应当在后续帧中保持存在」，而不是「这是给我的命令」。指令被执行的那些案例，可能是因为文字描述的动作恰好也是该场景最自然的续写（热气球本来就会飘、大象本来就会转身），标注只是加强了一个已有的先验，而不是引入了一个新的控制。</p><p>论文为此提供的证据是那张成功率表：嵌入式指令确实明显优于纯文本。但这只证明它比文本更好，没有证明模型在「执行指令」而不是「被标注偏置」。缺失的关键证据是反先验测试——让物体做它最不可能做的事。而论文中唯一一个这样的案例（让白车倒车，因为后面停着另一辆车）成功率只有 20.8%，恰恰是最弱的一项。这个数据点更支持「标注放大已有先验」而非「标注传达指令」。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，只需要一个开源模型（Wan 2.2）加 API 额度，目标是把「执行指令」与「放大先验」区分开。</p><p>数据与实现：构造 40 个场景，每个场景包含一个明确物体和一对<strong>互为反向</strong>的指令（球向左滚 / 球向右滚；门打开 / 门关闭；人坐下 / 人站起）。关键在于同一张底图配两个方向相反的标注，形成配对。另设一个先验强度分组：一半场景中两个方向的物理先验相当（平地上的球），另一半中一个方向明显违反常识或物理惯性（车向后开且后方有障碍、水向上流）。每种配置生成 12 条视频。</p><p>测量：人工或用一个固定 VLM judge 判定实际发生的动作方向，计算「按指令方向执行」的比例。同时记录一个对照量——不加任何标注、只给底图和空 prompt 时，物体自发运动的方向分布。</p><p>判据：如果在先验相当的组里两个方向的成功率都显著高于自发分布，说明标注确实携带了控制信息；如果成功率只在与自发分布一致的那个方向上高、反方向接近自发水平，那么这个接口本质上是先验放大器而不是指令通道，论文的定位需要修正。这个实验直接对准 §9 的假设，且成本很低。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，最有力的攻击是给出一个<strong>对定量优势的替代解释</strong>：嵌入式指令的收益来自输入分布，而不是空间接地。</p><p>具体论证如下。在 VBench 对比中，嵌入式设置把 prompt 文字放在图像<strong>上方</strong>作为 caption——这不是空间接地的用法（文字并不在目标物体旁边），却仍然拿到了更高的 Dynamic Degree（Veo3.1 0.8392 vs 0.7857，Kling 0.5625 vs 0.4218）。如果收益来自空间接地，这个设置下不该有系统性提升。一个更简单的解释是：把文字画进图里改变了首帧的图像统计（多了高对比度的文本区域、改变了画幅构图），而这种扰动本身就会降低模型对首帧的过拟合、增大输出的运动幅度。</p><p>攻击实验：在完全相同的三个模型上加一组消融——(a) 首帧叠加与任务无关的随机文字（如一段无意义字符或不相关的句子），文本 prompt 仍给正确的任务描述；(b) 首帧叠加一个纯色矩形块，面积与文字区域相当；(c) 论文的标准设置。比较三者的 Dynamic Degree 与运动相关指标。如果 (a) 和 (b) 也带来相近的 Dynamic Degree 提升，那么这项差异与「读懂了指令」无关，是纯粹的输入扰动效应，表 1 中唯一有利于本方法的那一列就失去了支撑力。</p><p>第二类可预测失败：指令密度。论文的所有例子最多是三个物体三条指令。随着物体数量增加，箭头与文字会互相遮挡、也会遮挡目标物体本身，而它们又必须留在画面里被模型「渲染」。可以预测在 6 个以上物体各配一条指令时，成功率会崩塌——不是因为模型不理解，而是因为画布本身的带宽用尽了。这是这个接口相对于专用条件编码器（可以在潜空间里携带任意多条控制信号）的结构性劣势。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>驱动局限：本文的控制信号必须画在<strong>可见的像素上</strong>，这带来两个绑在一起的问题——指令会残留在输出中（需要后处理），以及画布带宽有限（指令一多就互相遮挡）。作者把这两点分别当作局限列出，但它们其实是同一个根因：控制信道和内容信道是同一条。</p><p>新的 framing：与其把指令画在人眼可见的图层上，不如问一个更本质的问题——视频模型解析这些标注时，用的是什么内部表示？如果能找到这条通路，控制就可以直接下到那个表示上，不必经过像素。这把问题从「怎么画得更好」重新表述为「视觉指令在模型内部对应哪个方向」，是一个可解释性问题而非接口设计问题。</p><p>具体路径：把 In-Video Instruction 当作一个探针而不是终点。对同一底图，构造成对的「有标注 / 无标注」输入，采集模型各层的隐状态差，得到每类指令（左移、旋转、停止）在表示空间中的方向向量，并检验这些方向是否具有可加性与空间选择性（作用在对应物体的 token 上而非全局）。一旦这些方向被识别出来，控制就变成在推理时向特定空间位置的 token 加一个向量——指令不进入像素，因此不残留、不遮挡、也不受画布面积限制。这与本文的接口是同一个能力的两种实现，但去掉了可见性这个约束。</p><p>可借鉴的相邻工具：LLM 的 steering vector 与 representation engineering（用对比激活提取行为方向）；视觉模型的概念激活向量（TCAV）；以及扩散模型里针对特定 token 位置做注意力操控的编辑方法（prompt-to-prompt 一类）。</p><p>第一个实验：只做最简单的一类指令——平移方向。用一个开源模型（Wan 2.2），在 200 个单物体场景上分别用「向左」与「向右」的箭头标注生成，采集各层各去噪步的隐状态，按物体所在的空间 token 位置取差得到方向向量。然后在<strong>无任何标注</strong>的干净首帧上，把这个向量加到目标物体所在的 token 上，看能否复现出对应方向的运动。判据：如果能复现，且换一个物体位置加向量就能换一个被控物体，那么「空间选择性的表示级控制」成立，可以继续扩展到旋转、轨迹、多物体；如果加向量只能产生全局的运动倾向而无法定位，说明空间绑定发生在比该层更浅或更深的位置，需要逐层扫描——这个负结果本身也有价值，它会告诉我们视频模型在哪一层完成了「符号—物体」的绑定。</p>',60)])])}const u=a(n,[["render",i]]);export{c as __pageData,u as default};
